import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { CopyButton } from "@/registry/erbium/blocks/copy-button";

export default function StatefulIconExample() {
  return (
    <CopyButton
      value="Stateful icons animate between states."
      aria-label="Copy example text"
      variant="outline"
      timeout={1200}
    />
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
// oxlint-disable sonarjs/no-duplicate-string -- the registry build inlines these docs calls by their literal text
import CheckboxStateExample from "./variants/checkbox-state";

import type { Meta, StoryObj } from "@storybook/react";

import CopyFeedbackExample from "./variants/copy-feedback";



import RotatingChevronExample from "./variants/rotating-chevron";



const meta = {
  parameters: {
    docs: {
      description: {
        component: "Import from `@/registry/erbium/ui/stateful-icon`.

| Component           | Use it for                                                                  |
| ------------------- | --------------------------------------------------------------------------- |
| `StatefulIcon`      | Swapping the content of one slot, such as copy and check or play and pause. |
| `RotatingChevron`   | The open state of a disclosure trigger or submenu.                          |
| `CheckboxStateIcon` | The check and mixed marks of a checkbox surface.                            |

## StatefulIcon

Pass the current `state` and the content for every state. Changing `state` crossfades between them. Reduced-motion preferences swap them at once.

```tsx
<Button aria-label={playing ? "Pause" : "Play"} size="icon">
  <StatefulIcon
    state={playing ? "pause" : "play"}
    icons={{ pause: <Icon name="pause" />, play: <Icon name="play" /> }}
  />
</Button>
```

The icon is decorative, so name the control around it. It accepts the other `span` props, such as `data-icon` for button spacing.

Theme changes suppress transitions while the palette swaps. Add `data-theme-motion` to an icon that should still animate, such as a theme toggle's.

## RotatingChevron

The chevron turns while its trigger has `aria-expanded="true"`. Accordion, Collapsible, Select, Combobox, Cascader, NavigationMenu, DropdownMenu and Popover triggers work as they are, as do submenu triggers. Add `group/disclosure` to a custom trigger.

| Prop        | Values                             | Closed direction                                            |
| ----------- | ---------------------------------- | ----------------------------------------------------------- |
| `direction` | `"down"` (default), `"inline-end"` | Down for content below, toward the inline end for submenus. |

## Checkbox state

Checkbox, DropdownMenuCheckboxItem, ContextMenuCheckboxItem, and MenubarCheckboxItem share `CheckboxStateIcon`. Checking draws the mark with the same timing everywhere; indeterminate fields show the mixed-selection mark. Reduced-motion preferences show the final state immediately. Consumers of these components get the animation automatically.

When implementing another checkbox surface, keep its primitive indicator mounted and give it `group/check-indicator`. Place CheckboxStateIcon inside it so the primitive's `data-checked` and `data-indeterminate` attributes drive the animation. The icon is decorative; the checkbox primitive owns its accessible state. Do not replace the primitive with a clickable icon or add a second checked-state context.

## External documentation

Motion for React supplies the animated icon transitions and reduced motion support.

- [Motion for React](https://motion.dev/docs/react)",
      },
    },
  },
} satisfies Meta;

export default { ...meta, title: "Components/Stateful Icon",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const CopyFeedback: Story = {
  parameters: {
    docs: {
      description: { story: "`CopyButton` uses StatefulIcon internally for copy, success, and failure feedback. Use the block for copy actions instead of managing clipboard state and switching icons in the caller." },
      source: { code: "import { CopyButton } from "@/registry/erbium/blocks/copy-button";

export default function StatefulIconExample() {
  return (
    <CopyButton
      value="Stateful icons animate between states."
      aria-label="Copy example text"
      variant="outline"
      timeout={1200}
    />
  );
}
" },
    },
  },
  render: CopyFeedbackExample,
};

export const RotatingChevron: Story = {
  parameters: {
    docs: {
      description: { story: "The chevron follows its trigger's open state without props or extra classes." },
      source: { code: "import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/registry/erbium/ui/collapsible";
import { RotatingChevron as RotatingChevronIcon } from "@/registry/erbium/ui/stateful-icon";

export default function StatefulIconRotatingChevronExample() {
  return (
    <Collapsible className="w-72">
      <CollapsibleTrigger className="flex w-full items-center rounded-lg border px-3 py-2 text-start">
        Project details
        <RotatingChevronIcon className="ms-auto size-4" />
      </CollapsibleTrigger>
      <CollapsibleContent className="px-3 py-2 text-caption text-muted-foreground">
        The shared chevron follows the trigger’s open state.
      </CollapsibleContent>
    </Collapsible>
  );
}
" },
    },
  },
  render: RotatingChevronExample,
};

export const CheckboxState: Story = {
  parameters: {
    docs: {
      description: { story: "Toggle Show details in the field, dropdown, menubar, or context menu. They share the same state and draw-on checkmark when checked. Toggle it off and on again to replay the animation. Mixed selection uses the shared minus mark. Reduced-motion preferences remove both transitions." },
      source: { code: "import { useState } from "react";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuList,
  DropdownMenuCheckboxItem,
} from "@/registry/erbium/ui/dropdown-menu";
import {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuList,
  ContextMenuCheckboxItem,
} from "@/registry/erbium/ui/context-menu";
import {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarList,
  MenubarCheckboxItem,
} from "@/registry/erbium/ui/menubar";

export default function CheckboxStateExample() {
  const [checked, setChecked] = useState(false);

  return (
    <div className="grid gap-group">
      <Field orientation="horizontal">
        <Checkbox checked={checked} onCheckedChange={setChecked} />
        <FieldLabel>Show details</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Checkbox indeterminate />
        <FieldLabel>Mixed selection</FieldLabel>
      </Field>
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="outline" />}>
          View options
        </DropdownMenuTrigger>
        <DropdownMenuContent>
          <DropdownMenuList>
            <DropdownMenuCheckboxItem checked={checked} onCheckedChange={setChecked}>
              Show details
            </DropdownMenuCheckboxItem>
          </DropdownMenuList>
        </DropdownMenuContent>
      </DropdownMenu>
      <Menubar>
        <MenubarMenu>
          <MenubarTrigger>View</MenubarTrigger>
          <MenubarContent>
            <MenubarList>
              <MenubarCheckboxItem checked={checked} onCheckedChange={setChecked}>
                Show details
              </MenubarCheckboxItem>
            </MenubarList>
          </MenubarContent>
        </MenubarMenu>
      </Menubar>
      <ContextMenu>
        <ContextMenuTrigger className="rounded-lg border border-dashed p-panel text-control">
          Right-click for view options
        </ContextMenuTrigger>
        <ContextMenuContent>
          <ContextMenuList>
            <ContextMenuCheckboxItem checked={checked} onCheckedChange={setChecked}>
              Show details
            </ContextMenuCheckboxItem>
          </ContextMenuList>
        </ContextMenuContent>
      </ContextMenu>
    </div>
  );
}
" },
    },
  },
  render: CheckboxStateExample,
};

import StatefulIconExample from "../examples/stateful-icon-demo";

const Example = () => <StatefulIconExample />;

export default Example;

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/registry/erbium/ui/collapsible";
import { RotatingChevron as RotatingChevronIcon } from "@/registry/erbium/ui/stateful-icon";

export default function StatefulIconRotatingChevronExample() {
  return (
    <Collapsible className="w-72">
      <CollapsibleTrigger className="flex w-full items-center rounded-lg border px-3 py-2 text-start">
        Project details
        <RotatingChevronIcon className="ms-auto size-4" />
      </CollapsibleTrigger>
      <CollapsibleContent className="px-3 py-2 text-caption text-muted-foreground">
        The shared chevron follows the trigger’s open state.
      </CollapsibleContent>
    </Collapsible>
  );
}
